#include <cstddef>
#include <cstdint>
extern "C" double jaro_similarity(const int64_t*v,size_t n){if(!v||n<2||n>66)return -1e300;int64_t n1=v[0];if(n1<0||n1>32||1+size_t(n1)>=n)return -1e300;size_t p=1+size_t(n1);int64_t n2=v[p];if(n2<0||n2>32||n1<n2||n!=p+1+size_t(n2))return -1e300;for(size_t i=0;i<size_t(n1);i++)if(v[1+i]<0||v[1+i]>127)return -1e300;for(size_t i=0;i<size_t(n2);i++)if(v[p+1+i]<0||v[p+1+i]>127)return -1e300;if(n1==n2){bool eq=true;for(int i=0;i<n1;i++)if(v[1+i]!=v[p+1+i])eq=false;if(eq)return 1.0;}int r=int(n1/2)-1;if(r<0)r=0;bool m1[32]{},m2[32]{};int m=0;for(int i=0;i<n1;i++){int lo=i-r;if(lo<0)lo=0;int hi=i+r;if(hi>=n2)hi=int(n2)-1;for(int j=lo;j<=hi;j++)if(v[1+i]==v[p+1+j]&&!m2[j]){m++;m1[i]=true;m2[j]=true;break;}}if(!m)return 0.0;int t=0,j=0;for(int i=0;i<n1;i++)if(m1[i]){while(!m2[j])j++;if(v[1+i]!=v[p+1+j])t++;j++;}t/=2;return (double(m)/n1+double(m)/n2+double(m-t)/m)/3.0;}
